app.addEventListener("submit",function(e){if(e.target.matches("#name-form,#settings-form")){e.preventDefault();saveNames(e.target);return}if(e.target.matches("#topic-form")){e.preventDefault();const data=new FormData(e.target),k=String(data.get("category")||"normalCards"),v=String(data.get("text")||"").trim(),x=readContent();if(v&&!x[k].includes(v)){x[k].push(v);saveContent(x);try{const custom=JSON.parse(localStorage.getItem("ignite-custom-topics-v1")||"null")||{};for(const key of TOPIC_MANAGER_KEYS.filter(k=>!ROLE_KEYS.includes(k))){if(!Array.isArray(custom[key]))custom[key]=[]}if(!custom[k].includes(v))custom[k].push(v);localStorage.setItem("ignite-custom-topics-v1",JSON.stringify(custom))}catch{}}renderTopics();return}
if(e.target.matches("#role-form")){e.preventDefault();const data=new FormData(e.target),k=state.__topicCategory||"roleplayNormal",x=readContent();x[k].push(cleanRole({id:"custom-"+Date.now(),emoji:data.get("emoji"),name:data.get("name"),desc:data.get("desc"),items:[]}));saveContent(x);renderTopics();return}
if(e.target.matches("[data-role-scene-form]")){e.preventDefault();const ri=Number(e.target.dataset.roleSceneForm),k=state.__topicCategory||"roleplayNormal",data=new FormData(e.target),x=readContent();if(x[k]?.[ri])x[k][ri].items.push({context:String(data.get("context")||"").trim(),challenge:String(data.get("challenge")||"").trim()});saveContent(x);renderTopics();return}
if(e.target.matches("#profile-edit-form")){e.preventDefault();const d=new FormData(e.target);state.names.p1=String(d.get("p1")||"").trim();state.names.p2=String(d.get("p2")||"").trim();state.relationship=String(d.get("relationship")||"Couple");state.relationshipSince=String(d.get("relationshipSince")||"")||null;save();state.__profileScreen="hub";render();return}
if(e.target.matches("#relationship-profile-form")){e.preventDefault();const d=new FormData(e.target);state.relationship=String(d.get("relationship")||"Couple");state.relationshipSince=String(d.get("relationshipSince")||"")||null;save();state.__profileScreen="couple";render();return}
if(e.target.matches("#preferences-form")){e.preventDefault();handlePreferenceSubmit(e.target);setView("minigames");return}if(e.target.matches("#bond-goal-form")){e.preventDefault();const s=readBond(),goal=String(new FormData(e.target).get("goal")||"").trim();if(goal){s.goals.unshift({text:goal,done:false});writeBond(s)}renderBond();return}if(e.target.matches("#memory-form")){e.preventDefault();const form=e.target,data=new FormData(form),moment=String(data.get("moment")||"A moment together").trim(),note=String(data.get("note")||"").trim(),location=String(data.get("location")||"").trim(),memoryDate=String(data.get("memoryDate")||"").trim(),category=String(data.get("category")||"moment"),file=form.querySelector("input[name=photo]")?.files?.[0],editing=state.__editingMemory?getMemory(state.__editingMemory):null;
 const finish=photo=>{if(editing){updateMemory(editing.id,{moment,note,location,memoryDate:memoryDate||editing.memoryDate||new Date().toISOString().slice(0,10),category,photo:photo||editing.photo||""})}else{saveMemory({journey:state.currentJourney?.title||"Manual Memory",xp:getProgress().xp,moment,note,location,memoryDate:memoryDate||new Date().toISOString().slice(0,10),category,photo:photo||""});recordMemorySaved()}recordInteraction(editing?"memory-edit":"memory-save");delete state.__editingMemory;setView("memories")};
 if(file&&file.size>1024*1024){alert("Photo terlalu besar. Gunakan foto maksimal 1 MB.");return}
 if(file){const reader=new FileReader();reader.onload=()=>finish(String(reader.result||""));reader.readAsDataURL(file)}else finish("")}});
try{history.scrollRestoration="manual"}catch{};
clearAllTopicStorageOnce();load();if(!sessionStorage.getItem("ignite-welcome-seen")){state.view="welcome"}else if(!state.names.p1.trim()||!state.names.p2.trim()){state.view="names"}else if(state.view==="names"){state.view="home"}initAccessibility(app);render();requestAnimationFrame(resetViewport);